import{_ as o,o as a,c as t,aj as n}from"./chunks/framework.C6uXqnaX.js";const h=JSON.parse('{"title":"The Angular CLI","description":"","frontmatter":{"untranslated":true},"headers":[],"relativePath":"tools/cli.md","filePath":"tools/cli.md"}'),i={name:"tools/cli.md"};function r(l,e,s,c,d,u){return a(),t("div",null,e[0]||(e[0]=[n('<h1 id="the-angular-cli" tabindex="-1">The Angular CLI <a class="header-anchor" href="#the-angular-cli" aria-label="Permalink to &quot;The Angular CLI&quot;">​</a></h1><p>The Angular CLI is a command-line interface tool which allows you to scaffold, develop, test, deploy, and maintain Angular applications directly from a command shell.</p><p>Angular CLI is published on npm as the <code>@angular/cli</code> package and includes a binary named <code>ng</code>. Commands invoking <code>ng</code> are using the Angular CLI.</p><div class="tip custom-block"><p class="custom-block-title">Try Angular without local setup</p><p>If you are new to Angular, you might want to start with <a href="/tutorials/learn-angular">Try it now!</a>, which introduces the essentials of Angular in the context of a ready-made basic online store app for you to examine and modify. This standalone tutorial takes advantage of the interactive <a href="https://stackblitz.com" target="_blank" rel="noreferrer">StackBlitz</a> environment for online development. You don&#39;t need to set up your local environment until you&#39;re ready.</p></div><ul><li><a href="/tools/cli/setup-local"><strong>Getting Started</strong></a>: Install Angular CLI to create and build your first app.</li><li><a href="/cli"><strong>Command Reference</strong></a>: Discover CLI commands to make you more productive with Angular.</li><li><a href="/tools/cli/schematics"><strong>Schematics</strong></a>: Create and run schematics to generate and modify source files in your application automatically.</li><li><a href="/tools/cli/cli-builder"><strong>Builders</strong></a>: Create and run builders to perform complex transformations from your source code to generated build outputs.</li></ul><h2 id="cli-command-language-syntax" tabindex="-1">CLI command-language syntax <a class="header-anchor" href="#cli-command-language-syntax" aria-label="Permalink to &quot;CLI command-language syntax&quot;">​</a></h2><p>Angular CLI roughly follows Unix/POSIX conventions for option syntax.</p><h3 id="boolean-options" tabindex="-1">Boolean options <a class="header-anchor" href="#boolean-options" aria-label="Permalink to &quot;Boolean options&quot;">​</a></h3><p>Boolean options have two forms: <code>--this-option</code> sets the flag to <code>true</code>, <code>--no-this-option</code> sets it to <code>false</code>. You can also use <code>--this-option=false</code> or <code>--this-option=true</code>. If neither option is supplied, the flag remains in its default state, as listed in the reference documentation.</p><h3 id="array-options" tabindex="-1">Array options <a class="header-anchor" href="#array-options" aria-label="Permalink to &quot;Array options&quot;">​</a></h3><p>Array options can be provided in two forms: <code>--option value1 value2</code> or <code>--option value1 --option value2</code>.</p><h3 id="key-value-options" tabindex="-1">Key/value options <a class="header-anchor" href="#key-value-options" aria-label="Permalink to &quot;Key/value options&quot;">​</a></h3><p>Some options like <code>--define</code> expect an array of <code>key=value</code> pairs as their values. Just like array options, key/value options can be provided in two forms: <code>--define &#39;KEY_1=&quot;value1&quot;&#39; KEY_2=true</code> or <code>--define &#39;KEY_1=&quot;value1&quot;&#39; --define KEY_2=true</code>.</p><h3 id="relative-paths" tabindex="-1">Relative paths <a class="header-anchor" href="#relative-paths" aria-label="Permalink to &quot;Relative paths&quot;">​</a></h3><p>Options that specify files can be given as absolute paths, or as paths relative to the current working directory, which is generally either the workspace or project root.</p>',15)]))}const m=o(i,[["render",r]]);export{h as __pageData,m as default};
